CREDIT["starboard"] = "Footage: White Shark Ocean"
SPL = dict(wl=520, floe=dict(x=1300, w=640, h=70), seal=True)


def LINE(n=5, x0=-700, x1=420, t1=5.0, y=640, dz=0.13):
    """Five orcas abreast in a receding diagonal: each farther one smaller, higher, hazier; tall fins cut the surface."""
    out = []
    for k in reversed(range(n)):
        sc = 1 - dz * k
        out.append(dict(v="a", len=600 * sc, path=[[0, x0 + k * 150, y - k * 26], [t1, x1 + k * 150, y - k * 26]], seed=k, fog=[40, 90, 110, 0.14 * k], drift=2, bigFin=0.24))
    return out


def POD(n=4, big=None):
    m = [dict(v="b", len=900, x=1020, y=470), dict(v="a", len=640, x=560, y=630, z=-1), dict(v="c", len=560, x=1450, y=660), dict(v="a", len=600, x=1350, y=320, z=-1),
         dict(v="c", len=380, x=760, y=360, z=-2), dict(v="b", len=420, x=300, y=480, z=-2)]
    if big: m[1] = dict(v="a", len=1180, x=640, y=600)
    return m[:n]


def ROLE(text, t, x, y, end=None): return LB(text, t, x, y, end=end)


